#include <stdio.h>
#include <stdbool.h>

int main() {
    int k, n;
    if (scanf("%d %d", &k, &n) != 2) return 0;

    char alfabeto[100];
    char mensagem[1005];

    scanf("%s", alfabeto);
    scanf("%s", mensagem);

    bool presente[256] = {false};
    for (int i = 0; i < k; i++) {
        presente[(unsigned char)alfabeto[i]] = true;
    }

    bool valido = true;
    for (int i = 0; i < n; i++) {
        if (!presente[(unsigned char)mensagem[i]]) {
            valido = false;
            break;
        }
    }

    if (valido) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
